다음 C 프로그램의 실행 결과를 출력하라.

#include <stdio.h>

typedef struct Animal {
    int age;
    int (*speak)(struct Animal *self);
} Animal;

int baseSpeak(Animal *self) {
    return self->age * 1;
}

int dogSpeak(Animal *self) {
    int base = baseSpeak(self);
    return base + 10;
}

int catSpeak(Animal *self) {
    int base = baseSpeak(self);
    return base * 2;
}

int puppySpeak(Animal *self) {
    int base = dogSpeak(self);
    return base + 5;
}

int main(void) {
    Animal a1 = {3, baseSpeak};
    Animal a2 = {4, dogSpeak};
    Animal a3 = {5, catSpeak};
    Animal a4 = {2, puppySpeak};

    Animal *list[4] = {&a1, &a2, &a3, &a4};
    int total = 0;

    for (int i = 0; i < 4; i++) {
        int result = list[i]->speak(list[i]);
        printf("animal %d: %d\n", i, result);
        total += result;
    }

    printf("total=%d\n", total);

    return 0;
}

